<script setup lang="ts">
import { computed,onMounted,onBeforeUnmount,ref,watch } from 'vue'
import InformationRequestThread from './InformationRequestThread.vue'
import RequestChatWindow from './RequestChatWindow.vue'
const emit=defineEmits<{processing:[value:boolean]}>()
const props=defineProps<{employeeId?:number}>()
const items=ref<any[]>([]),pagination=ref({page:1,pages:1,total:0}),status=ref('Pending'),search=ref(''),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),opened=ref<number|null>(null),drafts=ref<Record<number,{message:string;status:string}>>({}),review=ref<any>(null)
const activeRequest=computed(()=>items.value.find(item=>item.RequestID===opened.value))
const canReply=computed(()=>['Pending','In review'].includes(activeRequest.value?.Status))
const draft=computed(()=>opened.value?drafts.value[opened.value]:undefined)
const preview=(item:any)=>item.messages?.[item.messages.length-1]?.Message||item.Message||'Open conversation'
const initials=(name:string)=>name.split(/[\s,]+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('')
let owner=0,controller:AbortController|null=null
watch(busy,value=>emit('processing',value))
async function load(page=1){const current=++owner;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const result:any=await $fetch('/api/employees/portal-accounts/requests',{query:{employeeId:props.employeeId,status:status.value||undefined,search:search.value.trim(),page},signal:controller.signal,retry:0,timeout:15000});if(current===owner){items.value=[...result.items];pagination.value=result.pagination;for(const item of items.value)if(!['Pending','In review'].includes(item.Status))delete drafts.value[item.RequestID];if(!activeRequest.value)opened.value=null;if(!canReply.value)review.value=null}}catch(cause:any){if(current===owner)error.value=cause?.data?.statusMessage||'Unable to load information requests.'}finally{if(current===owner)loading.value=false}}
function open(item:any){if(busy.value)return;if(['Pending','In review'].includes(item.Status))drafts.value[item.RequestID]??={message:'',status:'In review'};else delete drafts.value[item.RequestID];opened.value=item.RequestID;review.value=null;error.value='';notice.value=''}
function close(){if(busy.value)return;opened.value=null;review.value=null}
function prepare(item:any){if(!canReply.value||!draft.value||activeRequest.value?.RequestID!==item.RequestID)return;review.value={requestId:item.RequestID,version:item.Version,message:draft.value.message.trim(),status:draft.value.status}}
async function send(){if(!review.value||busy.value||!canReply.value)return;const body={...review.value},current=owner;busy.value=true;error.value='';notice.value='';try{await $fetch('/api/employees/portal-accounts/requests',{method:'POST',body,retry:0,timeout:20000});if(current!==owner)return;delete drafts.value[body.requestId];review.value=null;notice.value='Reply and request status saved. The employee record was not changed.';await load(pagination.value.page);if(activeRequest.value&&canReply.value)drafts.value[body.requestId]={message:'',status:activeRequest.value.Status}}catch(cause:any){if(current===owner)error.value=cause?.data?.statusMessage||'Unable to send this reply. Reload if the request changed.'}finally{busy.value=false}}
onMounted(()=>void load());watch(()=>props.employeeId,()=>{opened.value=null;drafts.value={};review.value=null;void load()});onBeforeUnmount(()=>{owner++;controller?.abort();emit('processing',false)})
</script>
<template>
 <section class="admin-requests"><header><p class="eyebrow">HR / PAYROLL INBOX</p><h3>Employee information requests</h3><p>Open a conversation to review a correction and reply. Update approved details in Employee Management before marking the request Resolved.</p></header>
  <form class="filters" @submit.prevent="load()"><label>Search employee or information<input v-model="search" type="search" placeholder="Name, employee number, or field"></label><label>Request status<select v-model="status"><option value="">All statuses</option><option>Pending</option><option>In review</option><option>Resolved</option><option>Declined</option><option>Cancelled</option></select></label><button type="submit" :disabled="loading||busy">Search</button></form>
  <p v-if="error&&!activeRequest" class="error" role="alert">{{error}} <button type="button" :disabled="busy" @click="load()">Reload</button></p><p v-if="notice&&!activeRequest" class="success" role="status">{{notice}}</p>
  <div class="list-heading"><small>{{pagination.total}} request{{pagination.total===1?'':'s'}}</small><span>Click a request to open messages</span></div>
  <div class="request-list"><article v-for="item in items" :key="item.RequestID"><button type="button" class="row" aria-haspopup="dialog" :disabled="busy" @click="open(item)"><span class="list-avatar" aria-hidden="true">{{initials(item.EmployeeName)}}</span><span class="list-identity"><strong>{{item.EmployeeName}}</strong><small>{{[item.EmployeeNumber,item.AgencyName].filter(Boolean).join(' / ')}}</small><span class="list-preview">{{preview(item)}}</span></span><span class="list-topic"><strong>{{item.FieldLabel}}</strong><small>#{{item.RequestID}} <span v-if="drafts[item.RequestID]?.message" class="draft-label"> / Draft</span></small></span><span class="status-badge" :class="{resolved:item.Status==='Resolved'}">{{item.Status}}</span><span class="open-arrow" aria-hidden="true">&#8599;</span></button></article><p v-if="!items.length" class="empty">{{loading?'Loading requests...':'No requests match your filters.'}}</p></div>
  <div v-if="pagination.pages>1" class="pages"><button type="button" :disabled="busy||loading||pagination.page<=1" @click="load(pagination.page-1)">Previous</button><small>{{pagination.page}} / {{pagination.pages}}</small><button type="button" :disabled="busy||loading||pagination.page>=pagination.pages" @click="load(pagination.page+1)">Next</button></div>
  <RequestChatWindow v-if="activeRequest" :title="activeRequest.EmployeeName" :subtitle="[activeRequest.EmployeeNumber,activeRequest.AgencyName].filter(Boolean).join(' / ')" :busy="busy" @close="close"><InformationRequestThread :request="activeRequest" viewer="staff" compact><template #composer><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><form v-if="canReply&&!review&&draft" class="reply-form" @submit.prevent="prepare(activeRequest)"><label>Reply to employee<textarea v-model="draft.message" required maxlength="2000" rows="2" :disabled="busy" placeholder="Write a reply..."></textarea></label><div class="reply-actions"><label>Set request status<select v-model="draft.status" :disabled="busy" required><option>In review</option><option>Resolved</option><option>Declined</option></select></label><button type="submit" class="primary" :disabled="busy">Review response</button></div><small>Closing this window keeps your draft. Employee details are updated separately.</small></form><div v-else-if="canReply&&review" class="review" aria-label="Review staff reply"><h4>Confirm reply &amp; status</h4><p>{{review.message}}</p><p>Status: <strong>{{review.status}}</strong></p><div><button type="button" :disabled="busy" @click="review=null">Keep editing</button><button type="button" class="primary" :disabled="busy" @click="send">{{busy?'Saving...':'Confirm and send'}}</button></div></div><p v-else class="closed-note">This request is {{activeRequest.Status.toLowerCase()}}. The conversation is read-only; further replies and status changes are disabled.</p></template></InformationRequestThread></RequestChatWindow>
 </section>
</template>
<style scoped>
.admin-requests{font:inherit;color:#1e385c;min-width:0}.admin-requests *{box-sizing:border-box}h3{font-size:1.25rem;margin:7px 0 10px}.eyebrow{font-size:.65rem;font-weight:800;letter-spacing:.09em;color:#2d64cc;margin:0}header>p:not(.eyebrow){font-size:.82rem;color:#647e9e;line-height:1.8;max-width:800px}button{min-height:40px;padding:10px 13px;border:1px solid #cbd9ed;border-radius:7px;background:#fff;color:#2d5da1;font:inherit;font-size:.77rem;font-weight:700;cursor:pointer}button:disabled{opacity:.5;cursor:default}.primary{background:#2863d9;color:#fff;border-color:#2863d9}.filters{display:grid;grid-template-columns:minmax(0,1fr) 190px auto;gap:12px;align-items:end;margin:22px 0}label{display:grid;gap:7px;font-size:.73rem;color:#4d678b;font-weight:700}input,select,textarea{box-sizing:border-box;width:100%;min-width:0;max-width:100%;padding:10px 12px;border:1px solid #cbd8eb;border-radius:7px;background:#fff;color:#18375f;font:inherit;font-size:.84rem}.list-heading{display:flex;justify-content:space-between;gap:12px;margin-top:22px;color:#8b9bb0;font-size:.68rem}.list-heading small{font-size:inherit}.request-list{border:1px solid #d9e3f1;border-radius:11px;background:#fff;overflow:hidden;margin-top:12px}.request-list>article+article{border-top:1px solid #e8eef6}.row{display:flex;gap:17px;align-items:center;width:100%;border:0;border-radius:0;text-align:left;padding:17px 20px;background:#fff}.row:hover{background:#f7faff}.row>span{min-width:0}.list-avatar{width:39px;height:39px;border-radius:9px;background:#edf3fd;color:#4172b4;display:grid;place-items:center;flex-shrink:0;font-size:.73rem}.list-identity{flex:1}.list-identity strong{display:block;font-size:.83rem;overflow-wrap:anywhere}.list-identity small{display:block;font-size:.66rem;font-weight:400;line-height:1.7;color:#8a9bb2;margin-top:4px}.list-preview{display:block;color:#6e85a2;font-weight:400;font-size:.72rem;margin-top:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:650px}.list-topic{flex:0 0 145px}.list-topic strong{display:block;font-size:.73rem;color:#53759d}.list-topic small{display:block;color:#93a3b8;font-size:.63rem;font-weight:400;margin-top:6px}.status-badge{padding:5px 8px;border-radius:5px;background:#fff3da;color:#9f7426;font-size:.62rem;white-space:nowrap}.status-badge.resolved{background:#e8f6ee;color:#2e805b}.open-arrow{font-size:.95rem;color:#7892b5}.draft-label{color:#af7d31}.reply-form{display:grid;gap:11px;margin:0}.reply-form textarea{resize:vertical;max-height:140px;font-size:16px}.reply-actions{display:flex;gap:12px;align-items:end}.reply-actions label{flex:1;min-width:0;font-size:.65rem}.reply-actions button{font-size:.68rem;flex-shrink:0}.reply-form>small,.closed-note{font-size:.63rem;color:#8a9bb2;line-height:1.7;margin:0}.review h4{margin:0;font-size:.85rem}.review p{font-size:.8rem;white-space:pre-wrap;line-height:1.7;overflow-wrap:anywhere}.review>div,.pages{display:flex;gap:10px;align-items:center}.review button{font-size:.69rem}.pages{justify-content:flex-end;margin-top:18px}.error,.success{padding:11px;border-radius:7px;font-size:.75rem;line-height:1.7;background:#fff0f0;color:#a32f3c}.success{background:#eaf8ef;color:#246e4a}.empty{padding:30px;text-align:center;color:#6b819d;font-size:.83rem}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #adc9f5;outline-offset:2px}@media(max-width:700px){.filters{grid-template-columns:1fr}.row{padding:16px;gap:11px;flex-wrap:wrap}.list-identity{flex-basis:calc(100% - 52px)}.list-topic{margin-left:50px;flex:1}.list-heading>span{display:none}.list-preview{max-width:100%}.reply-actions{gap:8px}.reply-actions button{padding:9px;font-size:.65rem}input,select,textarea{font-size:16px}.open-arrow{display:none}}
